]
$arianny_data$::jsonb) AS source_data (
  source_row integer, sku text, name text, stock numeric, unit text, cost numeric, price numeric
);

DO $$
BEGIN
  IF (SELECT count(*) FROM arianny_source) <> 2318
     OR (SELECT count(*) FROM arianny_source WHERE unit = 'pz') <> 2173
     OR (SELECT count(*) FROM arianny_source WHERE unit = 'kg') <> 145 THEN
    RAISE EXCEPTION 'El origen debe contener 2318 filas: 2173 pz y 145 kg.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM arianny_source
    WHERE NULLIF(btrim(sku), '') IS NULL OR NULLIF(btrim(name), '') IS NULL
      OR stock IS NULL OR unit IS NULL OR unit NOT IN ('pz', 'kg')
      OR cost IS NULL OR price IS NULL OR cost <= 0 OR price <= 0
      OR stock::text IN ('NaN', 'Infinity', '-Infinity')
      OR cost::text IN ('NaN', 'Infinity', '-Infinity')
      OR price::text IN ('NaN', 'Infinity', '-Infinity')
      OR round(cost * 100) NOT BETWEEN 1 AND 2147483647
      OR round(price * 100) NOT BETWEEN 1 AND 2147483647
      OR round(GREATEST(stock, 0), 3) > 9999999.999
      OR (unit = 'pz' AND stock <> trunc(stock))
  ) THEN
    RAISE EXCEPTION 'Hay datos obligatorios vacíos, unidades inválidas o importes/existencias fuera de rango.';
  END IF;

  IF EXISTS (SELECT 1 FROM arianny_source GROUP BY lower(btrim(sku)) HAVING count(*) > 1) THEN
    RAISE EXCEPTION 'El archivo contiene SKU duplicados, ignorando mayúsculas y espacios externos.';
  END IF;

  IF (SELECT count(*) FROM arianny_source WHERE stock < 0) <> 46 THEN
    RAISE EXCEPTION 'Se esperaban exactamente 46 existencias negativas para normalizar a cero.';
  END IF;

  IF (SELECT count(*) FROM arianny_source
      WHERE source_row = 1241 AND sku = 'SANA01' AND name = chr(92) AND unit = 'kg') <> 1 THEN
    RAISE EXCEPTION 'No coincide la fila SANA01 cuya exclusión fue acordada.';
  END IF;
END $$;

CREATE TEMP TABLE arianny_target (
  account_id text PRIMARY KEY,
  user_id text NOT NULL
) ON COMMIT DROP;

-- Preventivo: el identificador recibido pertenece a Account, NO a User.
-- Se verificaron ambos IDs por separado: no inferir que Account.id y User.id coinciden.
-- Exigir el propietario activo de ESTA cuenta evita cargar datos en otra empresa.
-- Los bloqueos compartidos mantienen el usuario y su cuenta mientras dura la carga.
INSERT INTO arianny_target (account_id, user_id)
SELECT app_user."accountId", app_user.id
FROM "User" app_user
JOIN "Account" account ON account.id = app_user."accountId"
WHERE account.id = 'cmwfsf3b200017fyly4xxnwty'
  AND app_user.id = 'cmwfsga6h001wns0saga3wbk8'
  AND app_user."isOwner" = true
  AND app_user."isActive" = true
FOR SHARE OF app_user, account;

DO $$
BEGIN
  IF (SELECT count(*) FROM arianny_target) <> 1 THEN
    RAISE EXCEPTION 'No existe la cuenta cmwfsf3b200017fyly4xxnwty con su propietario activo cmwfsga6h001wns0saga3wbk8. No se cargó ningún producto.';
  END IF;
END $$;

CREATE TEMP TABLE arianny_products (
  source_row integer PRIMARY KEY,
  sku text NOT NULL,
  name text NOT NULL,
  cost_cents integer NOT NULL,
  price_cents integer NOT NULL,
  stock numeric(10,3) NOT NULL,
  product_kind "ProductKind" NOT NULL,
  unit "UnitType" NOT NULL
) ON COMMIT DROP;

-- Preventivo: normalizar solo los negativos; los ceros originales siguen siendo cero.
-- Decimal(10,3) admite tres decimales. Producto y movimiento usan la MISMA cantidad,
-- evitando diferencias por redondear el movimiento a dos decimales.
INSERT INTO arianny_products (source_row, sku, name, cost_cents, price_cents, stock, product_kind, unit)
SELECT source_row, btrim(sku), name,
       round(cost * 100)::integer,
       round(price * 100)::integer,
       round(GREATEST(stock, 0), 3),
       CASE unit WHEN 'pz' THEN 'BASIC'::"ProductKind" ELSE 'MEASURED'::"ProductKind" END,
       CASE unit WHEN 'pz' THEN 'UNIDAD'::"UnitType" ELSE 'KG'::"UnitType" END
FROM arianny_source
WHERE sku <> 'SANA01';

DO $$
BEGIN
  IF (SELECT count(*) FROM arianny_products) <> 2317
     OR (SELECT count(*) FROM arianny_products WHERE product_kind = 'BASIC' AND unit = 'UNIDAD') <> 2173
     OR (SELECT count(*) FROM arianny_products WHERE product_kind = 'MEASURED' AND unit = 'KG') <> 144
     OR EXISTS (SELECT 1 FROM arianny_products WHERE stock < 0 OR cost_cents <= 0 OR price_cents <= 0) THEN
    RAISE EXCEPTION 'La preparación no coincide con los 2317 productos y tipos acordados.';
  END IF;
END $$;

-- Preventivo: Prisma calcula @updatedAt en el cliente; SQL directo debe asignarlo.
-- El upsert bloquea el consecutivo de esta cuenta hasta COMMIT y respeta un consecutivo
-- adelantado. Las altas normales también reservan números mediante ProductSequence.
INSERT INTO "ProductSequence" (id, "accountId", "lastNumber", "updatedAt")
SELECT 'sql_' || md5(random()::text || clock_timestamp()::text), target.account_id,
       COALESCE((SELECT max(product."productId") FROM "Product" product
                 WHERE product."accountId" = target.account_id), 0),
       CURRENT_TIMESTAMP
FROM arianny_target target
ON CONFLICT ("accountId") DO UPDATE
SET "lastNumber" = GREATEST("ProductSequence"."lastNumber", EXCLUDED."lastNumber"),
    "updatedAt" = CURRENT_TIMESTAMP;

CREATE TEMP TABLE arianny_new_rows ON COMMIT DROP AS
SELECT source.*,
       (sequence."lastNumber" + row_number() OVER (ORDER BY source.source_row))::integer AS product_number
FROM arianny_products source
CROSS JOIN arianny_target target
JOIN "ProductSequence" sequence ON sequence."accountId" = target.account_id
WHERE NOT EXISTS (
  SELECT 1 FROM "Product" existing
  WHERE existing."accountId" = target.account_id
    AND lower(btrim(existing.sku)) = lower(source.sku)
);

CREATE TEMP TABLE arianny_inserted_products (
  id text PRIMARY KEY,
  account_id text NOT NULL,
  sku text NOT NULL,
  product_number integer NOT NULL,
  stock numeric(10,3) NOT NULL,
  product_kind "ProductKind" NOT NULL
) ON COMMIT DROP;

-- Sin categorías ni proveedores inventados. Se usan los defaults del modelo para
-- ITBIS (1800), stock mínimo (0), imágenes y estados de venta/actividad/demo.
WITH inserted AS (
  INSERT INTO "Product" (
    id, "accountId", "productId", name, sku, reference,
    "costCents", "priceCents", stock, "productKind", unit, "updatedAt"
  )
  SELECT 'sql_' || md5(random()::text || clock_timestamp()::text || source.source_row::text),
         target.account_id, source.product_number, source.name, source.sku, NULL,
         source.cost_cents, source.price_cents, source.stock, source.product_kind, source.unit,
         CURRENT_TIMESTAMP
  FROM arianny_new_rows source
  CROSS JOIN arianny_target target
  ORDER BY source.source_row
  RETURNING id, "accountId", sku, "productId", stock, "productKind"
)
INSERT INTO arianny_inserted_products (id, account_id, sku, product_number, stock, product_kind)
SELECT id, "accountId", sku, "productId", stock, "productKind" FROM inserted;

CREATE TEMP TABLE arianny_inserted_movements (product_id text PRIMARY KEY) ON COMMIT DROP;

-- Un movimiento por producto NUEVO, incluso cuando su existencia inicial es cero.
-- Se usa el usuario indicado; nunca se toma un usuario de otra cuenta.
WITH inserted AS (
  INSERT INTO "InventoryAdjustment" (id, "accountId", "productId", "userId", "qtyDelta", reason)
  SELECT 'sql_' || md5(random()::text || clock_timestamp()::text || product.id),
         product.account_id, product.id, target.user_id, product.stock, 'Stock inicial'
  FROM arianny_inserted_products product
  JOIN arianny_target target ON target.account_id = product.account_id
  RETURNING "productId"
)
INSERT INTO arianny_inserted_movements (product_id) SELECT "productId" FROM inserted;

UPDATE "ProductSequence" sequence
SET "lastNumber" = sequence."lastNumber" + (SELECT count(*)::integer FROM arianny_inserted_products),
    "updatedAt" = CURRENT_TIMESTAMP
FROM arianny_target target
WHERE sequence."accountId" = target.account_id;

-- Las comprobaciones finales ocurren ANTES de COMMIT: cualquier diferencia revierte todo.
DO $$
BEGIN
  IF (SELECT count(*) FROM arianny_inserted_products) <> (SELECT count(*) FROM arianny_new_rows)
     OR (SELECT count(*) FROM arianny_inserted_movements) <> (SELECT count(*) FROM arianny_inserted_products) THEN
    RAISE EXCEPTION 'No coincide la cantidad de productos nuevos con sus movimientos de inventario.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM arianny_inserted_products inserted
    JOIN "Product" product ON product.id = inserted.id
    JOIN arianny_products source ON source.sku = inserted.sku
    CROSS JOIN arianny_target target
    WHERE product."accountId" IS DISTINCT FROM target.account_id
      OR product."productId" IS DISTINCT FROM inserted.product_number
      OR product.name IS DISTINCT FROM source.name
      OR product.sku IS DISTINCT FROM source.sku
      OR product.reference IS NOT NULL
      OR product."supplierId" IS NOT NULL OR product."categoryId" IS NOT NULL
      OR product."costCents" IS DISTINCT FROM source.cost_cents
      OR product."priceCents" IS DISTINCT FROM source.price_cents
      OR product.stock IS DISTINCT FROM source.stock
      OR product."productKind" IS DISTINCT FROM source.product_kind
      OR product.unit IS DISTINCT FROM source.unit
      OR product."itbisRateBp" IS DISTINCT FROM 1800 OR product."minStock" IS DISTINCT FROM 0
      OR product."isActive" IS DISTINCT FROM true
      OR product."isAvailableForSale" IS DISTINCT FROM true
      OR product."isOnboardingDemo" IS DISTINCT FROM false
  ) THEN
    RAISE EXCEPTION 'Los productos insertados no coinciden con los datos y defaults acordados.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM arianny_inserted_products product
    CROSS JOIN arianny_target target
    LEFT JOIN "InventoryAdjustment" movement ON movement."productId" = product.id
    GROUP BY product.id, product.account_id, product.stock, target.user_id
    HAVING count(movement.id) <> 1
      OR bool_or(movement."accountId" IS DISTINCT FROM product.account_id
                 OR movement."userId" IS DISTINCT FROM target.user_id
                 OR movement."qtyDelta" IS DISTINCT FROM product.stock
                 OR movement.reason IS DISTINCT FROM 'Stock inicial')
  ) THEN
    RAISE EXCEPTION 'Los movimientos iniciales no coinciden con su producto, usuario o existencia.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM arianny_products source
    CROSS JOIN arianny_target target
    WHERE NOT EXISTS (SELECT 1 FROM "Product" product
                      WHERE product."accountId" = target.account_id
                        AND lower(btrim(product.sku)) = lower(source.sku))
  ) THEN
    RAISE EXCEPTION 'Faltan SKU del origen en la cuenta destino.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM "ProductSequence" sequence
    JOIN arianny_target target ON target.account_id = sequence."accountId"
    WHERE sequence."lastNumber" < (SELECT max(product."productId") FROM "Product" product
                                  WHERE product."accountId" = target.account_id)
  ) THEN
    RAISE EXCEPTION 'El consecutivo quedó por debajo de los productos de la cuenta.';
  END IF;
END $$;

SELECT target.account_id, target.user_id,
       (SELECT count(*) FROM arianny_source) AS source_rows,
       1 AS source_rows_excluded,
       (SELECT count(*) FROM arianny_products) AS eligible_products,
       (SELECT count(*) FROM arianny_source WHERE stock < 0) AS negative_stocks_set_to_zero,
       (SELECT count(*) FROM arianny_products WHERE product_kind = 'BASIC') AS source_basic_products,
       (SELECT count(*) FROM arianny_products WHERE product_kind = 'MEASURED') AS source_measured_products,
       (SELECT count(*) FROM arianny_inserted_products) AS products_created,
       (SELECT count(*) FROM arianny_products) - (SELECT count(*) FROM arianny_inserted_products)
         AS products_skipped_as_existing,
       (SELECT count(*) FROM arianny_inserted_products WHERE product_kind = 'BASIC') AS basic_products_created,
       (SELECT count(*) FROM arianny_inserted_products WHERE product_kind = 'MEASURED') AS measured_products_created,
       (SELECT count(*) FROM arianny_inserted_movements) AS initial_stock_movements,
       sequence."lastNumber" AS final_product_sequence
FROM arianny_target target
JOIN "ProductSequence" sequence ON sequence."accountId" = target.account_id;

COMMIT;
